/* ===================== BÀI 15 · MUL/IMUL, DIV/IDIV ===================== */
/* Bài 15 · MUL/IMUL, DIV/IDIV (AMTS-EMB-002-M04-L03, X86-015) — sinh bởi tools/author/mpu8086/l15.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P15=[{"label": "Ví dụ: MUL 8 bit và 16 bit", "code": "; Ví dụ 1: MUL 8 bit và 16 bit, thanh ghi ngầm định\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ntich16  DD      ?                       ; DX:AX\ntich8   DW      ?                       ; AX\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AL, 25\n        MOV     BL, 12\n        MUL     BL                      ; AX = AL × BL = 300 = 012Ch\n        MOV     tich8, AX\n        MOV     AX, 1000\n        MOV     CX, 300\n        MUL     CX                      ; DX:AX = AX × CX = 300000\n        MOV     WORD PTR tich16, AX\n        MOV     WORD PTR tich16+2, DX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bấm Từng bước tới MUL BL: AX đổi thành 012Ch (300), cờ CF và OF thành 1 vì AH khác 0. MUL CX nhân AX với CX và ghi cả DX: DX:AX = 0004 93E0h = 300 000. Cột chu kỳ hiện 70 và 118 (cận dưới; khoảng đầy đủ hiện khi chạm vào). Đoán trước: sau MUL CX, DX bằng bao nhiêu? Đáp án 0004h."}, {"label": "Ví dụ: cùng mẫu bit, MUL khác IMUL", "code": "; Ví dụ 2: cùng mẫu bit, MUL và IMUL cho hai kết quả\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nkqmul   DW      ?\nkqimul  DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AL, 0FEH                ; 254 không dấu, -2 có dấu\n        MOV     BL, 3\n        MUL     BL                      ; 254 × 3 = 762 = 02FAh\n        MOV     kqmul, AX\n        MOV     AL, 0FEH\n        IMUL    BL                      ; -2 × 3 = -6 = FFFAh\n        MOV     kqimul, AX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Cùng AL = FEh, BL = 03h. MUL hiểu FEh là 254: AX = 762 = 02FAh. IMUL hiểu FEh là −2: AX = −6 = FFFAh. Byte thấp giống nhau (FAh), byte cao khác. Đoán trước: sau IMUL BL, AX bằng bao nhiêu? Đáp án FFFAh."}, {"label": "Ví dụ: DIV 8 bit và 16 bit, thương và dư", "code": "; Ví dụ 3: DIV 8 bit và 16 bit: thương và số dư\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nthuong16 DW     ?\ndu16    DW      ?\nthuong8 DB      ?\ndu8     DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, 100                 ; số bị chia 8 bit: AX\n        MOV     BL, 7\n        DIV     BL                      ; AL = 14 (thương), AH = 2 (dư)\n        MOV     thuong8, AL\n        MOV     du8, AH\n        MOV     DX, 1                   ; số bị chia 16 bit: DX:AX\n        MOV     AX, 86A0H               ; DX:AX = 0001 86A0h = 100000\n        MOV     CX, 7\n        DIV     CX                      ; AX = 14285, DX = 5\n        MOV     thuong16, AX\n        MOV     du16, DX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "DIV BL chia AX (không phải AL) cho BL: 100 / 7 cho AL = 14 (0Eh), AH = 2. DIV CX chia cả DX:AX = 0001 86A0h = 100 000 cho 7: AX = 14 285 (37CDh), DX = 5. Một lần chia cho cả thương và số dư. Đoán trước: sau DIV BL, AH bằng bao nhiêu? Đáp án 02h."}, {"label": "Lỗi: DX còn số dư cũ trước DIV", "code": "; Ví dụ 4 (lỗi cố ý): DX còn số dư cũ trước DIV\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nq1      DW      ?\nsai     DW      ?\ndung    DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, 1000\n        MOV     BX, 7\n        MOV     DX, 0\n        DIV     BX                      ; AX = 142, DX = 6 (số dư)\n        MOV     q1, AX\n        MOV     AX, 50000               ; muốn tính 50000 / 7\n        DIV     BX                      ; sai: chia DX:AX = 6 × 65536 + 50000\n        MOV     sai, AX\n        XOR     DX, DX                  ; sửa: xóa DX trước mỗi DIV 16 bit\n        MOV     AX, 50000\n        DIV     BX                      ; AX = 7142\n        MOV     dung, AX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi logic cố ý: sau lần chia đầu, DX = 6 (số dư). Lần chia thứ hai quên xóa DX nên số bị chia là 6 × 65 536 + 50 000 = 443 216, thương 63 316 (F754h) thay vì 7142 (1BE6h). Thương vẫn vừa AX nên không có lỗi chia: lỗi im lặng. Sửa: XOR DX, DX trước mỗi DIV 16 bit (đoạn cuối). Đoán trước: ngay trước DIV BX thứ hai, DX bằng bao nhiêu? Đáp án 0006h."}, {"label": "Lỗi: thương quá lớn, lỗi chia", "code": "; Ví dụ 5 (lỗi cố ý): thương không vừa AL → lỗi chia\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AX, 1000\n        MOV     BL, 2\n        DIV     BL                      ; 1000 / 2 = 500 > 255: ngắt 0\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi chạy cố ý: 1000 / 2 = 500 không vừa AL (tối đa 255), CPU sinh ngắt 0. Trình mô phỏng dừng ở lệnh DIV BL và giải thích; DOS thật in “Divide overflow”. Sửa: chia 16 bit (XOR DX, DX / MOV BX, 2 / DIV BX), xem Hình 15.1. Đoán trước: lệnh DIV BL có chạy xong không? Đáp án không."}, {"label": "Ví dụ: IDIV số âm, chuẩn bị bằng CBW, CWD", "code": "; Ví dụ 6: IDIV với số âm, chuẩn bị bằng CBW, CWD\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nthuong16 DW     ?\ndu16    DW      ?\nthuong8 DB      ?\ndu8     DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AL, -100\n        CBW                             ; AX = FF9Ch = -100\n        MOV     BL, 7\n        IDIV    BL                      ; AL = -14 (F2h), AH = -2 (FEh)\n        MOV     thuong8, AL\n        MOV     du8, AH\n        MOV     AX, -1000\n        CWD                             ; DX:AX = -1000\n        MOV     CX, 7\n        IDIV    CX                      ; AX = -142, DX = -6\n        MOV     thuong16, AX\n        MOV     du16, DX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "CBW biến AL = −100 (9Ch) thành AX = FF9Ch. IDIV BL: −100 / 7 cho AL = −14 (F2h), AH = −2 (FEh): thương cắt về 0, số dư cùng dấu số bị chia. CWD chuẩn bị DX:AX = −1000; IDIV CX cho AX = −142 (FF72h), DX = −6 (FFFAh). Đoán trước: sau IDIV BL, AH bằng bao nhiêu (hệ 16)? Đáp án FEh."}, {"label": "Bẫy: số bị chia âm cần CWD", "code": "; Ví dụ 7 (bẫy): số bị chia âm cần CWD, không phải XOR\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nsai     DW      ?\ndung    DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, -1000               ; FC18h\n        XOR     DX, DX                  ; DX:AX = 0000 FC18h = +64536\n        MOV     CX, 7\n        IDIV    CX                      ; 64536 / 7 = 9219: sai\n        MOV     sai, AX\n        MOV     AX, -1000\n        CWD                             ; DX:AX = FFFF FC18h = -1000\n        IDIV    CX                      ; -142: đúng\n        MOV     dung, AX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bẫy cố ý: AX = −1000 = FC18h. XOR DX, DX làm DX:AX = 0000 FC18h = +64 536, nên IDIV cho 9219 (2403h). CWD làm DX = FFFFh, DX:AX = −1000, IDIV cho −142 đúng. Đoán trước: sau CWD, DX bằng bao nhiêu? Đáp án FFFFh."}, {"label": "Ví dụ: một lần DIV cho cả hai chữ số", "code": "; Ví dụ 8: một lần DIV cho cả hai chữ số\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AX, 47\n        MOV     BL, 10\n        DIV     BL                      ; AL = 4 (chục), AH = 7 (đơn vị)\n        ADD     AX, 3030H               ; cộng '0' vào cả hai byte\n        MOV     BX, AX\n        MOV     DL, BL                  ; '4'\n        MOV     AH, 02H\n        INT     21H\n        MOV     DL, BH                  ; '7'\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Một lần DIV BL cho cả chữ số hàng chục (AL = 4) và hàng đơn vị (AH = 7). ADD AX, 3030h cộng mã '0' (30h) vào cả hai byte cùng lúc. Màn hình in 47. Đoán trước: sau DIV BL, AX bằng bao nhiêu? Đáp án 0704h."}];
const sim15=makeX86Sim(document.getElementById("x86-l15"),{id:"s15",presets:P15,file:"BAI15.ASM"});
makeX86Ex(document.getElementById("ex-l15"),sim15,[{"t": "Tích hai chữ số", "d": "Đọc hai phím chữ số '0'–'9' bằng INT 21h hàm 08h (code mẫu đã đổi chữ số thứ nhất thành giá trị trong BL, chữ số thứ hai trong AL). Ghi tích của hai giá trị vào biến word tich. Không in gì; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 1: tích hai chữ số\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ntich    DW      ?                       ; a × b\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H\n        INT     21H\n        SUB     AL, '0'                 ; AL = a\n        MOV     BL, AL\n        MOV     AH, 08H\n        INT     21H\n        SUB     AL, '0'                 ; AL = b\n; Viết code ở đây: tich = a × b\n\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "34", "mem": [{"at": "tich", "word": 12}]}, {"in": "99", "mem": [{"at": "tich", "word": 81}]}, {"in": "00", "mem": [{"at": "tich", "word": 0}]}, {"in": "90", "mem": [{"at": "tich", "word": 0}]}, {"in": "17", "mem": [{"at": "tich", "word": 7}]}, {"in": "58", "mem": [{"at": "tich", "word": 40}]}]}, {"t": "Thương và dư khi chia 7", "d": "Đọc ba phím chữ số (hàng trăm, hàng chục, hàng đơn vị) bằng INT 21h hàm 08h. Ghi số tạo thành (0–999) vào biến word so, thương của so chia 7 vào biến byte thuong, số dư vào biến byte du. Không in gì; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 2: số 3 chữ số, thương và dư khi chia 7\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nso      DW      ?                       ; số 3 chữ số\nthuong  DB      ?                       ; so / 7\ndu      DB      ?                       ; so mod 7\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H\n        INT     21H\n        SUB     AL, '0'                 ; chữ số hàng trăm\n; Viết code ở đây: đọc thêm 2 chữ số, tính so,\n; rồi thuong, du\n\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "999", "mem": [{"at": "so", "word": 999}, {"at": "thuong", "bytes": [142]}, {"at": "du", "bytes": [5]}]}, {"in": "000", "mem": [{"at": "so", "word": 0}, {"at": "thuong", "bytes": [0]}, {"at": "du", "bytes": [0]}]}, {"in": "007", "mem": [{"at": "so", "word": 7}, {"at": "thuong", "bytes": [1]}, {"at": "du", "bytes": [0]}]}, {"in": "123", "mem": [{"at": "so", "word": 123}, {"at": "thuong", "bytes": [17]}, {"at": "du", "bytes": [4]}]}, {"in": "500", "mem": [{"at": "so", "word": 500}, {"at": "thuong", "bytes": [71]}, {"at": "du", "bytes": [3]}]}, {"in": "006", "mem": [{"at": "so", "word": 6}, {"at": "thuong", "bytes": [0]}, {"at": "du", "bytes": [6]}]}]}, {"t": "Đổi giây ra giờ, phút, giây", "d": "Hai phím đọc bằng INT 21h hàm 08h là hai byte của số giây n: phím 1 là byte thấp, phím 2 là byte cao (giả định của đề: thiết bị gửi byte thấp trước). Ghi n / 3600 vào gio, (n mod 3600) / 60 vào phut, n mod 60 vào giay (ba biến byte). Code mẫu đúng nhưng chậm. Viết lại để đạt cả giới hạn chu kỳ và giới hạn số byte mã. Không in gì; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 3: đổi số giây ra giờ, phút, giây\n; Bản này đúng nhưng chậm: tính lại số dư bằng MUL\n; và chia 16 bit hai lần. Hãy viết lại.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nn       DW      ?                       ; số giây\ngio     DB      ?\nphut    DB      ?\ngiay    DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H\n        INT     21H\n        MOV     BYTE PTR n, AL          ; byte thấp\n        MOV     AH, 08H\n        INT     21H\n        MOV     BYTE PTR n+1, AL        ; byte cao\n        MOV     AX, n\n        XOR     DX, DX\n        MOV     CX, 3600\n        DIV     CX                      ; AX = giờ\n        MOV     gio, AL\n        MUL     CX                      ; AX = giờ × 3600\n        MOV     BX, n\n        SUB     BX, AX                  ; BX = số giây còn lại\n        MOV     AX, BX\n        XOR     DX, DX\n        MOV     CX, 60\n        DIV     CX                      ; AX = phút, DX = giây\n        MOV     phut, AL\n        MOV     giay, DL\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "AB", "mem": [{"at": "gio", "bytes": [4]}, {"at": "phut", "bytes": [42]}, {"at": "giay", "bytes": [41]}]}, {"in": "  ", "mem": [{"at": "gio", "bytes": [2]}, {"at": "phut", "bytes": [17]}, {"at": "giay", "bytes": [4]}]}, {"in": "~~", "mem": [{"at": "gio", "bytes": [8]}, {"at": "phut", "bytes": [59]}, {"at": "giay", "bytes": [42]}]}, {"in": "0P", "mem": [{"at": "gio", "bytes": [5]}, {"at": "phut", "bytes": [42]}, {"at": "giay", "bytes": [8]}]}, {"in": "z!", "mem": [{"at": "gio", "bytes": [2]}, {"at": "phut", "bytes": [22]}, {"at": "giay", "bytes": [50]}]}, {"in": "pE", "mem": [{"at": "gio", "bytes": [4]}, {"at": "phut", "bytes": [56]}, {"at": "giay", "bytes": [16]}]}], "perf": {"cycles": 460, "bytes": 50}}]);

makeQuiz("quiz15","score15",[{"q": "Sau đoạn sau, AX và CF bằng bao nhiêu?<pre class=\"mp-asm\">        MOV     AL, 20\n        MOV     BL, 15\n        MUL     BL<\/pre>", "o": ["AX = 002Ch, CF = 1", "AX = 012Ch, CF = 1", "AX = 012Ch, CF = 0", "AX = 2C01h, CF = 0"], "a": 1, "e": "20 × 15 = 300 = 012Ch nằm trong AX. AH = 01h khác 0 nên MUL đặt CF = OF = 1."}, {"q": "AX chứa số không dấu 50 000. Muốn chia cho CX = 7 bằng DIV CX. Lệnh nào phải có ngay trước DIV?", "o": ["<code>XOR DX, DX<\/code>", "<code>CWD<\/code>", "<code>CBW<\/code>", "<code>MOV AH, 0<\/code>"], "a": 0, "e": "DIV 16 bit chia cả DX:AX. Số không dấu cần DX = 0. CWD sẽ đặt DX = FFFFh vì bit 15 của 50 000 (C350h) bằng 1."}, {"q": "Sau đoạn sau, AX và DX bằng bao nhiêu?<pre class=\"mp-asm\">        MOV     AX, -7\n        CWD\n        MOV     BX, 2\n        IDIV    BX<\/pre>", "o": ["AX = FFFDh (−3), DX = FFFFh (−1)", "AX = FFFCh (−4), DX = 0001h (1)", "AX = 0003h (3), DX = 0001h (1)", "Lỗi chia vì số bị chia âm"], "a": 0, "e": "IDIV cắt thương về 0: −7 / 2 = −3, số dư cùng dấu số bị chia: −7 − (−3 × 2) = −1."}, {"q": "Đoạn nào gây lỗi chia (ngắt 0)?", "o": ["<code>MOV AX, 500<\/code> / <code>MOV BL, 2<\/code> / <code>DIV BL<\/code>", "<code>XOR DX, DX<\/code> / <code>MOV AX, 600<\/code> / <code>MOV BX, 2<\/code> / <code>DIV BX<\/code>", "<code>MOV AX, 600<\/code> / <code>MOV BL, 2<\/code> / <code>DIV BL<\/code>", "<code>MOV AX, 255<\/code> / <code>MOV BL, 1<\/code> / <code>DIV BL<\/code>"], "a": 2, "e": "600 / 2 = 300 không vừa AL (tối đa 255). 500 / 2 = 250 và 255 / 1 = 255 vẫn vừa; chia 16 bit cho thương 300 trong AX."}, {"q": "AX chứa số không dấu từ 0 tới 999. Cần thương và số dư khi chia 7. Cách nào đúng và ít chu kỳ nhất?", "o": ["<code>XOR DX, DX<\/code> / <code>MOV BX, 7<\/code> / <code>DIV BX<\/code>", "<code>MOV BL, 7<\/code> / <code>DIV BL<\/code> (thương ở AL, dư ở AH)", "<code>CWD<\/code> / <code>MOV BX, 7<\/code> / <code>IDIV BX<\/code>", "<code>MOV BL, 7<\/code> / <code>DIV BL<\/code>, rồi <code>MUL BL<\/code> và <code>SUB<\/code> để tính số dư"], "a": 1, "e": "999 / 7 = 142 vừa AL nên DIV 8 bit an toàn (cận dưới 80 chu kỳ, so với 144 của DIV 16 bit và 165 của IDIV 16 bit). Số dư đã có ở AH, không cần MUL rồi SUB."}]);

